const body = $json.body || $json;

const candidateId = body.candidateId || 'cand_demo_reject';
const candidateName = body.name || body.candidateName || 'Ứng viên';
const candidateEmail = body.email || body.candidateEmail || 'doanthanhhuy130978@gmail.com';
const jobTitle = body.jobTitle || 'Chuyên viên Công nghệ';
const matchScore = Number(body.matchScore !== undefined ? body.matchScore : 45);
const skills = Array.isArray(body.parsedSkillsJson) ? body.parsedSkillsJson : ['Kỹ năng chuyên môn'];
const skillsStr = Array.isArray(skills) ? skills.join(', ') : String(skills);
const companyName = body.companyName || 'Công ty Cổ phần Công nghệ HR Tech Hub';

const senderName = body.senderName || 'Bộ phận Thu hút & Phát triển Nhân tài';
const senderPhone = body.senderPhone || '0901 234 567';
const senderEmail = body.senderEmail || 'recruitment@company.com';

// 1. Phân loại kịch bản từ chối (3 Kịch bản thực tế của người dùng)
// - Scenario 1 (CV_SCREENING): Loại ở vòng duyệt hồ sơ (< 50%)
// - Scenario 2 (POST_INTERVIEW): Đã tham gia phỏng vấn/bài test nhưng chưa đạt (50% - 69%)
// - Scenario 3 (TOP_TALENT): Ứng viên ấn tượng cao nhưng hết chỉ tiêu (70% - 79%)
let scenarioCode = (body.rejectionType || body.stage || '').toUpperCase();

if (!scenarioCode) {
  if (matchScore >= 70) {
    scenarioCode = 'TOP_TALENT';
  } else if (matchScore >= 50) {
    scenarioCode = 'POST_INTERVIEW';
  } else {
    scenarioCode = 'CV_SCREENING';
  }
}

let emailSubject = '';
let emailHtml = '';
let scenarioTitle = '';
let talentPoolTier = '';
let summaryForBackend = '';

const archivedAt = new Date().toISOString();

if (scenarioCode === 'CV_SCREENING') {
  scenarioTitle = 'Từ chối vòng duyệt hồ sơ (Screening)';
  talentPoolTier = 'GENERAL_TALENT_POOL';
  emailSubject = `Thư phản hồi hồ sơ ứng tuyển vị trí ${jobTitle} – ${companyName}`;

  const paragraphs = `
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Chúng tôi thuộc bộ phận nhân sự thuộc công ty <strong>${companyName}</strong> nhận được hồ sơ ứng tuyển của bạn. Rất cám ơn vì sự quan tâm của bạn đối với vị trí việc làm <strong>${jobTitle}</strong>.
    </p>
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Tuy nhiên, sau khi xem xét các hồ sơ, chúng tôi nhận thấy bạn chưa phù hợp để chọn vào vòng phỏng vấn.
    </p>
    <p style="font-size: 15px; color: #334155; margin-bottom: 24px;">
      Chúc bạn may mắn trong quá trình tìm việc sau đó và hi vọng sẽ có cơ hội được hợp tác với bạn trong tương lai.
    </p>
  `;

  emailHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: Arial, 'Segoe UI', Helvetica, sans-serif; background-color: #f8fafc; margin: 0; padding: 24px; color: #1e293b; line-height: 1.6;">
  <div style="max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.06);">
    <div style="background: linear-gradient(135deg, #334155 0%, #475569 100%); height: 8px; width: 100%;"></div>
    <div style="padding: 32px 28px;">
      <p style="margin-top: 0; font-size: 15px; font-weight: 600; color: #0f172a;">Thân gửi ${candidateName},</p>
      ${paragraphs}
      <div style="font-size: 14px; color: #475569; border-top: 1px solid #e2e8f0; padding-top: 20px; line-height: 1.5;">
        <p style="margin: 0 0 6px 0;">Trân trọng,</p>
        <p style="margin: 0; font-weight: 700; color: #0f172a;">${senderName}</p>
        <p style="margin: 0; color: #0f172a; font-weight: 600;">${companyName}</p>
      </div>
    </div>
  </div>
</body>
</html>`;

  summaryForBackend = `[TỪ CHỐI VÒNG HỒ SƠ]: Đã gửi thư từ chối vòng hồ sơ lịch thiệp cho ứng viên ${candidateName}. Lưu vào General Talent Pool.`;

} else if (scenarioCode === 'POST_INTERVIEW') {
  scenarioTitle = 'Từ chối sau vòng phỏng vấn/bài test & Lưu hồ sơ';
  talentPoolTier = 'RETAINED_TALENT_POOL';
  emailSubject = `Thư phản hồi kết quả phỏng vấn vị trí ${jobTitle} – ${companyName}`;

  const paragraphs = `
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Một lần nữa cám ơn bạn đã tham gia buổi phỏng vấn cho vị trí việc làm <strong>${jobTitle}</strong> tại <strong>${companyName}</strong>. Với sự cố gắng và nhiệt tình của bạn cùng với những sẻ chia và cam kết sẽ đóng góp của bạn đã được chúng tôi đánh giá rất cao trong buổi phỏng vấn này. Song, sau khi xem xét và bàn bạc lại, chúng tôi chỉ quyết định lựa chọn một số ứng viên ấn tượng hơn để tiếp tục đồng hành cùng chúng tôi.
    </p>
    <div style="background-color: #f8fafc; border-left: 4px solid #64748b; border-radius: 6px; padding: 16px 18px; margin: 20px 0; font-size: 14px; color: #334155;">
      Và chúng tôi sẽ giữ lại hồ sơ của bạn để có thể tiếp tục liên hệ lại với bạn nếu công ty có nhu cầu tuyển dụng mới và phù hợp trong thời gian tới.
    </div>
    <p style="font-size: 15px; color: #334155; margin-bottom: 24px;">
      Trân trọng và chúc bạn luôn gặp nhiều may mắn và thành công trong quá trình tìm việc.
    </p>
  `;

  emailHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: Arial, 'Segoe UI', Helvetica, sans-serif; background-color: #f8fafc; margin: 0; padding: 24px; color: #1e293b; line-height: 1.6;">
  <div style="max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.06);">
    <div style="background: linear-gradient(135deg, #1e293b 0%, #334155 100%); height: 8px; width: 100%;"></div>
    <div style="padding: 32px 28px;">
      <p style="margin-top: 0; font-size: 15px; font-weight: 600; color: #0f172a;">Mến gửi ${candidateName},</p>
      ${paragraphs}
      <div style="font-size: 14px; color: #475569; border-top: 1px solid #e2e8f0; padding-top: 20px; line-height: 1.5;">
        <p style="margin: 0 0 6px 0;">Trân trọng,</p>
        <p style="margin: 0; font-weight: 700; color: #0f172a;">${senderName}</p>
        <p style="margin: 0; color: #0f172a; font-weight: 600;">${companyName}</p>
      </div>
    </div>
  </div>
</body>
</html>`;

  summaryForBackend = `[TỪ CHỐI SAU PHỎNG VẤN]: Đã gửi thư cảm ơn & thông báo lưu giữ hồ sơ vào Retained Talent Pool cho ứng viên ${candidateName}.`;

} else { // TOP_TALENT
  scenarioTitle = 'Ứng viên tiềm năng cao (hết chỉ tiêu) & Ưu tiên liên hệ';
  talentPoolTier = 'PRIORITY_TALENT_POOL';
  emailSubject = `Thư phản hồi & Cảm ơn ứng viên vị trí ${jobTitle} – ${companyName}`;

  const paragraphs = `
    <p style="font-size: 15px; color: #334155; margin-bottom: 16px;">
      Chúng tôi rất cám ơn bạn đã dành nhiều thời gian để tham gia ứng tuyển với vị trí <strong>${jobTitle}</strong> tại <strong>${companyName}</strong>. Có thể nói ngay từ đầu chúng tôi cũng rất ấn tượng với hồ sơ của bạn và tất cả những điều mà bạn đã thể hiện trong quá trình phỏng vấn. Tuy nhiên, một số ứng viên đã được ban tuyển dụng quyết định chọn lựa trên cơ sở cân nhắc rất kỹ lưỡng và thấu đáo.
    </p>
    <div style="background-color: #f1f5f9; border-left: 4px solid #2563eb; border-radius: 6px; padding: 16px 18px; margin: 20px 0; font-size: 14px; color: #1e293b;">
      Một lần nữa xin cám ơn những ý kiến của bạn đối với doanh nghiệp chúng tôi. Và hãy giữ liên hệ với chúng tôi vì trong tương lai, chúng tôi vẫn còn có nhu cầu tuyển dụng trở lại. Nếu có vấn đề gì thắc mắc bạn liên hệ với chúng tôi qua số <strong>${senderPhone}</strong> hoặc email <strong>${senderEmail}</strong>.
    </div>
    <p style="font-size: 15px; color: #334155; margin-bottom: 24px;">
      Chúc bạn thành công.
    </p>
  `;

  emailHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: Arial, 'Segoe UI', Helvetica, sans-serif; background-color: #f8fafc; margin: 0; padding: 24px; color: #1e293b; line-height: 1.6;">
  <div style="max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.06);">
    <div style="background: linear-gradient(135deg, #1e3a8a 0%, #1e293b 100%); height: 8px; width: 100%;"></div>
    <div style="padding: 32px 28px;">
      <p style="margin-top: 0; font-size: 15px; font-weight: 600; color: #0f172a;">${candidateName} thân mến!</p>
      ${paragraphs}
      <div style="font-size: 14px; color: #475569; border-top: 1px solid #e2e8f0; padding-top: 20px; line-height: 1.5;">
        <p style="margin: 0 0 6px 0;">Trân trọng,</p>
        <p style="margin: 0; font-weight: 700; color: #0f172a;">${senderName}</p>
        <p style="margin: 0; color: #0f172a; font-weight: 600;">${companyName}</p>
        <p style="margin: 4px 0 0 0; font-size: 13px; color: #64748b;">Hotline: ${senderPhone} | Email: ${senderEmail}</p>
      </div>
    </div>
  </div>
</body>
</html>`;

  summaryForBackend = `[PRIORITY TALENT POOL]: Ứng viên ấn tượng cao ${candidateName} (${matchScore}%). Đã gửi thư cảm ơn trân trọng & lưu trữ ưu tiên liên hệ lại.`;
}

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    companyName,
    matchScore,
    skills,
    scenarioCode,
    scenarioTitle,
    talentPoolTier,
    emailSubject,
    emailHtml,
    senderName,
    senderPhone,
    senderEmail,
    summaryForBackend,
    archivedAt
  }
}];

const data = $('Phân Loại Kịch Bản & Soạn Thư Từ Chối').first().json;

return [{
  json: {
    channel: 'HR_TALENT_POOL_REGISTRY',
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    scenario: data.scenarioCode,
    scenarioTitle: data.scenarioTitle,
    talentPoolTier: data.talentPoolTier,
    archivedAt: data.archivedAt,
    retentionPolicy: data.scenarioCode === 'TOP_TALENT' ? 'Ưu tiên liên hệ lại ngay khi có đợt tuyển dụng mới' : 'Lưu trữ hồ sơ dự phòng',
    status: 'RECORDED_IN_TALENT_POOL'
  }
}];

parameters.jsonBody:
={
  "matchScore": {{ $json.matchScore }},
  "summary": {{ JSON.stringify($json.summaryForBackend) }},
  "parsedSkillsJson": {
    "skills": {{ JSON.stringify($json.skills) }},
    "talentPool": {
      "status": "ARCHIVED",
      "scenario": {{ JSON.stringify($json.scenarioCode) }},
      "tier": {{ JSON.stringify($json.talentPoolTier) }},
      "archivedAt": {{ JSON.stringify($json.archivedAt) }},
      "emailSent": true
    }
  }
}

parameters.jsCode:
const data = $('Phân Loại Kịch Bản & Soạn Thư Từ Chối').first().json;
const backendSyncResult = $json;

return [{
  json: {
    success: true,
    action: "CANDIDATE_REJECTION_AND_TALENT_POOL_ARCHIVED",
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    scenario: {
      code: data.scenarioCode,
      title: data.scenarioTitle,
      tier: data.talentPoolTier
    },
    emailDelivery: {
      recipient: data.candidateEmail,
      subject: data.emailSubject,
      smtpStatus: "DISPATCHED"
    },
    backendSync: {
      status: backendSyncResult?.id ? "SYNCED_TO_DATABASE" : "STANDALONE_SIMULATED",
      updatedCandidateId: backendSyncResult?.id || data.candidateId
    },
    archivedAt: data.archivedAt
  }
}];
